import{g as a,ae as e,r as t,B as n}from"./chunks/framework.CZ-ntRvv.js";const _=JSON.parse('{"title":"Resource","description":"","frontmatter":{},"headers":[],"relativePath":"docs/data-fetching/resource.md","filePath":"docs/data-fetching/resource.md","lastUpdated":1790261415000}'),p={name:"docs/data-fetching/resource.md"};function c(o,s,d,r,l,i){return e(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="resource" tabindex="-1">Resource <a class="header-anchor" href="#resource" aria-label="Permalink to “Resource”">​</a></h1><p><code>createResource</code> fetches data from a URL and gives you a reactive object with the data, loading and error state, and methods to fetch again. It is the older data-fetching API and stays supported through <code>1.x</code>.</p><p>For new code, use <a href="./use-call"><code>useCall</code></a>.</p><h2 id="composition-api" tabindex="-1">Composition API <a class="header-anchor" href="#composition-api" aria-label="Permalink to “Composition API”">​</a></h2><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">Button</span><span class="s_1i4ay4"> :loading</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todos.loading</span><span class="s_w1p9wo">&quot;</span><span class="s_1i4ay4"> @click</span><span class="s_1jjt6x">=</span><span class="s_w1p9wo">&quot;</span><span class="s_2575z4">todos.reload()</span><span class="s_w1p9wo">&quot;</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">Reload</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">Button</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">pre</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">{{ todos.data }}</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">pre</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1i4ay4"> setup</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">createResource</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"></span>
<span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> todos</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> createResource</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe.client.get_list</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  params</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_r4oegk"> filters</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span><span class="s_12xt1b"> status</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">Open</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  auto</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>The short URL <code>frappe.client.get_list</code> works when the app uses <a href="#frappe-backend"><code>frappeRequest</code></a>. With the default fetcher, write the full path, <code>/api/method/frappe.client.get_list</code>.</p><h2 id="options-api" tabindex="-1">Options API <a class="header-anchor" href="#options-api" aria-label="Permalink to “Options API”">​</a></h2><p>Install the FrappeUI plugin with the <code>resources</code> option:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1th9sy">// main.js</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">FrappeUI</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_22m8k2">app</span><span class="s_1jjt6x">.</span><span class="s_indoxt">use</span><span class="s_13ahmt">(</span><span class="s_22m8k2">FrappeUI</span><span class="s_1jjt6x">,</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> resources</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_13ahmt"> })</span></span></code></pre></div><p>Then declare resources under the <code>resources</code> key. Each one is a function that returns the options, and the resource is available on <code>this.$resources.&lt;name&gt;</code>. When a value the function reads changes, the resource is created again with the new options.</p><div class="language-vue"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">  &lt;</span><span class="s_1uuh8p">pre</span><span class="s_1zd9e2">&gt;</span><span class="s_6am9cx">{{ $resources.todos.data }}</span><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">pre</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">template</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"></span>
<span class="line"><span class="s_1zd9e2">&lt;</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span>
<span class="line"><span class="s_edvzsf">export</span><span class="s_edvzsf"> default</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">  resources</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_indoxt">    todos</span><span class="s_13ahmt">()</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_29n2kq">      return</span><span class="s_13ahmt"> {</span></span>
<span class="line"><span class="s_r4oegk">        url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe.client.get_list</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">        params</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> { </span><span class="s_12xt1b">doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">        auto</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">      }</span></span>
<span class="line"><span class="s_13ahmt">    }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">  }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">}</span></span>
<span class="line"><span class="s_1zd9e2">&lt;/</span><span class="s_1uuh8p">script</span><span class="s_1zd9e2">&gt;</span></span></code></pre></div><p>Add <code>type: &#39;list&#39;</code> or <code>type: &#39;document&#39;</code> to create a <a href="./list-resource">list resource</a> or a <a href="./document-resource">document resource</a> instead. <code>resourcesPlugin</code> is the same plugin, exported for apps that do not install <code>FrappeUI</code>.</p><h2 id="frappe-backend" tabindex="-1">Frappe backend <a class="header-anchor" href="#frappe-backend" aria-label="Permalink to “Frappe backend”">​</a></h2><p>By default, resources use <code>request</code>, a small wrapper around <code>fetch</code>. For a Frappe backend, set <code>frappeRequest</code> as the fetcher once in <code>main.js</code>:</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">setConfig</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> frappeRequest</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_indoxt">setConfig</span><span class="s_13ahmt">(</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">resourceFetcher</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_22m8k2"> frappeRequest</span><span class="s_13ahmt">)</span></span></code></pre></div><p>With <code>frappeRequest</code>:</p><ul><li>A URL that does not start with <code>/</code> or <code>http</code> gets the <code>/api/method/</code> prefix, so <code>frappe.client.get_list</code> works.</li><li>The default method is <code>POST</code>. With <code>request</code>, it is <code>GET</code>.</li><li><code>data</code> is the <code>message</code> key of the response, and a failed request sets <code>error</code> with the server&#39;s exception details.</li></ul><h2 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to “Caching”">​</a></h2><p>Set <code>cache</code> to a key to keep the response in memory and in IndexedDB. Another <code>createResource</code> call with the same key returns the same resource object. On a page reload, the stored response shows until the new request finishes.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_252irl">const</span><span class="s_295sjd"> todos</span><span class="s_2ekfrt"> =</span><span class="s_indoxt"> createResource</span><span class="s_13ahmt">({</span></span>
<span class="line"><span class="s_r4oegk">  url</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe.client.get_list</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  params</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> {</span><span class="s_r4oegk"> doctype</span><span class="s_1jjt6x">:</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">ToDo</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt"> }</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  cache</span><span class="s_1jjt6x">:</span><span class="s_13ahmt"> [</span><span class="s_w1p9wo">&#39;</span><span class="s_2575z4">todos</span><span class="s_w1p9wo">&#39;</span><span class="s_1jjt6x">,</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">open</span><span class="s_w1p9wo">&#39;</span><span class="s_13ahmt">]</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_r4oegk">  auto</span><span class="s_1jjt6x">:</span><span class="s_40mev6"> true</span><span class="s_1jjt6x">,</span></span>
<span class="line"><span class="s_13ahmt">})</span></span></code></pre></div><p>The key is a string or an array that can be turned into JSON. It is read once, when the resource is created, so changing a ref inside it later does not change the key.</p><h2 id="api-reference" tabindex="-1">API Reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to “API Reference”">​</a></h2><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>url</code></td><td></td><td>A path (<code>/api/posts/1</code>), a full URL, or a dotted method name with <code>frappeRequest</code>.</td></tr><tr><td><code>method</code></td><td><code>GET</code> (<code>POST</code> with <code>frappeRequest</code>)</td><td>HTTP method: <code>GET</code>, <code>POST</code>, <code>PUT</code> or <code>DELETE</code>.</td></tr><tr><td><code>params</code></td><td></td><td>Parameters for the request. Sent as the query string for <code>GET</code>, as a JSON body otherwise.</td></tr><tr><td><code>makeParams(params)</code></td><td></td><td>Returns the parameters for each request. Receives the value passed to <code>fetch()</code> or <code>submit()</code>.</td></tr><tr><td><code>auto</code></td><td><code>false</code></td><td>Fetch once when the resource is created.</td></tr><tr><td><code>initialData</code></td><td><code>null</code></td><td>Value of <code>data</code> before the first response.</td></tr><tr><td><code>debounce</code></td><td></td><td>Wait this many milliseconds after the last call before sending the request.</td></tr><tr><td><code>cache</code></td><td></td><td>String or array key. See <a href="#caching">Caching</a>.</td></tr><tr><td><code>resourceFetcher</code></td><td></td><td>Fetch function for this resource only. Overrides the <code>resourceFetcher</code> config.</td></tr><tr><td><code>validate(params)</code></td><td></td><td>Runs before the request. Return a string (or throw) to fail with that message. Can be async.</td></tr><tr><td><code>beforeSubmit(params)</code></td><td></td><td>Runs before the request, after <code>validate</code>.</td></tr><tr><td><code>onFetch(params)</code></td><td></td><td>Runs when a fetch starts.</td></tr><tr><td><code>onSuccess(data)</code></td><td></td><td>Runs with the raw response after a successful request.</td></tr><tr><td><code>onData(data)</code></td><td></td><td>Runs after a successful request, and when cached data loads from IndexedDB.</td></tr><tr><td><code>onError(error)</code></td><td></td><td>Runs when the request or <code>validate</code> fails. Without it, the <code>fallbackErrorHandler</code> config runs.</td></tr><tr><td><code>transform(data)</code></td><td></td><td>Changes the response before it is set on <code>data</code>. Return the new value, or change <code>data</code> in place.</td></tr></tbody></table><h3 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h3><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><code>data</code></td><td>The response, after <code>transform</code>.</td></tr><tr><td><code>loading</code></td><td><code>true</code> while a request is in progress.</td></tr><tr><td><code>error</code></td><td>The error from the last request or from <code>validate</code>.</td></tr><tr><td><code>fetched</code></td><td><code>true</code> after the first successful response, until <code>reset()</code>.</td></tr><tr><td><code>promise</code></td><td>The promise of the current request. You can await it.</td></tr><tr><td><code>params</code></td><td>The parameters sent with the last request, after <code>makeParams</code>.</td></tr><tr><td><code>previousData</code></td><td>A copy of <code>data</code> from before the last request started.</td></tr></tbody></table><h3 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>fetch(params?)</code></td><td>Send the request. Returns a promise of <code>data</code> that rejects if the request fails.</td></tr><tr><td><code>reload(params?)</code></td><td>Same as <code>fetch</code>.</td></tr><tr><td><code>submit(params?)</code></td><td>Same as <code>fetch</code>. Use it for requests that change data, like <code>post.submit({ id: 2 })</code>.</td></tr><tr><td><code>abort()</code></td><td>Cancel the request in progress. It does not set <code>error</code>.</td></tr><tr><td><code>reset()</code></td><td>Reset the resource to its state when it was created.</td></tr><tr><td><code>update({ params, auto })</code></td><td>Change the parameters or <code>auto</code> for later requests. It also accepts <code>url</code> and <code>method</code>, but later requests still use the ones from the options.</td></tr><tr><td><code>setData(data)</code></td><td>Replace <code>data</code>. Pass a function to compute it from the current data: <code>setData((d) =&gt; d.filter((t) =&gt; t.open))</code>.</td></tr></tbody></table>`,28)])])}const u=a(p,[["render",c]]);export{_ as __pageData,u as default};
